gnv(){return"\uc774 \ubcf4\uc7a5\uc740 \uae30\uc900 \ud45c\ubcf8\uacfc \uac80\uc0ac \ub300\uc0c1\uc774 \uad50\ud658 \uac00\ub2a5\ud558\ub2e4\ub294 \uac83, \uc989 \uac19\uc740 \uc9d1\ub2e8\xb7\uac19\uc740 \uc885\ub958\uc758 \uacfc\uc81c\ub77c\ub294 \uc804\uc81c\uc5d0 \uae30\ub311\ub2c8\ub2e4. \ud559\uc0dd\uc758 \uae00\uc4f0\uae30 \uc2e4\ub825\uc774 \ub69c\ub837\uc774 \ub298\uc5c8\uac70\ub098 \uacfc\uc81c \uc720\ud615\uc774 \uc644\uc804\ud788 \ubc14\ub00c\uc5c8\ub2e4\uba74 \uc804\uc81c\uac00 \ubb34\ub108\uc9c0\ubbc0\ub85c \uae30\uc900 \uc138\ud2b8\ub97c \ub2e4\uc2dc \ub9cc\ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4. \ub610\ud55c \uae30\uc900 \uae00 \uc790\uccb4\uac00 AI \ub300\ud544\uc774\ub77c\uba74 \ubcf4\uc815 \uc804\uccb4\uac00 \ud2c0\uc5b4\uc9c0\ubbc0\ub85c \ud1b5\uc81c\ub41c \ud658\uacbd\uc5d0\uc11c \uc218\uc9d1\ud558\uc138\uc694."},
gnt(){return"\uc774 \uae00\uc744 \uae30\uc900 \uc138\ud2b8\uc5d0 \ucd94\uac00"},
nu(a){return"\uae30\uc900 \uc138\ud2b8\uc5d0 \ucd94\uac00\ud588\uc2b5\ub2c8\ub2e4 \u2014 \ud604\uc7ac "+a+"\ud3b8"},
gmG(){return"\ub85c\uceec \uae30\uc900 \uc138\ud2b8"},
mF(a,b){return"\ud604\uc7ac "+a+"\ud3b8(\uc774 \u03b1\uc5d0\ub294 "+b+"\ud3b8 \ud544\uc694)"},
gmD(){return"\uae30\uc900 \uc138\ud2b8 \ube44\uc6b0\uae30"},
gmE(){return"\uae30\uc900 \uc138\ud2b8\ub97c \ube44\uc6e0\uc2b5\ub2c8\ub2e4"},
gmC(){return"\uc624\ud0d0\ub960 \uc0c1\ud55c(\u03b1)"},
mB(a,b){return"\ud604\uc7ac "+a+"% \u2014 \ub0ae\uc744\uc218\ub85d \uc5c4\uaca9\ud558\uc9c0\ub9cc \uae30\uc900 \ud45c\ubcf8\uc774 \ub354 \ub9ce\uc774 \ud544\uc694\ud569\ub2c8\ub2e4(\ucd5c\uc18c "+b+"\ud3b8)"},
rq(a,b,c){return"AI \ud655\ub960 "+a+"% / AI \ud45c\uc2dc \uae30\uc900\uac12 "+b+"% = AI index "+c+"%"},
glo(){return"\uc99d\uac70\uac00 \ubd80\uc871\ud558\uc5ec \ud310\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4"},
nm(a,b){return"\ubd84\uc11d \uac00\ub2a5\ud55c \ubb38\uc7a5\uc774 "+a+"\uac1c\ubfd0\uc785\ub2c8\ub2e4(\ucd5c\uc18c "+b+"\uac1c \ud544\uc694). \uc774 \uae38\uc774\uc5d0\uc11c\ub294 \ud1b5\uacc4\xb7\ubb38\uc7a5 \ub2e8\uc704 \uc2e0\ud638\uac00 \uc758\ubbf8\ub97c \uac16\uc9c0 \ubabb\ud558\uba70, \uc5b5\uc9c0\ub85c \uc810\uc218\ub97c \ub0b4\uba74 \uc624\ud574\ub9cc \ubd80\ub985\ub2c8\ub2e4."},
nn(a,b){return"\ubcf8\ubb38\uc774 "+a+"\ub2e8\uc5b4\ub85c, \ucd5c\uc18c "+b+"\ub2e8\uc5b4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4. \uadf8 \uc544\ub798\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubb38\uccb4 \ud2b9\uc9d5\ub3c4 \uc6b0\uc5f0\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4."},
nl(a,b){return""+b+"\uac1c \uc911 "+a+"\uac1c \uc5d4\uc9c4\ub9cc \ucc38\uc5ec\ud574 \ub2e4\ub978 \uac01\ub3c4\uc5d0\uc11c \uad50\ucc28 \uac80\uc99d\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ucc44\uc6b4 \ub4a4 \ub2e4\uc2dc \uc2e4\ud589\ud558\uc138\uc694."},
nk(a){return"\uc5d4\uc9c4 \uac04 \ucc28\uc774\uac00 "+a+"\ud37c\uc13c\ud2b8\ud3ec\uc778\ud2b8\ub85c, \ud3c9\uade0\uc744 \ub0b4\ub294 \uac83\uc774 \uc758\ubbf8\ub97c \uc783\uc744 \ub9cc\ud07c \uac08\ub9bd\ub2c8\ub2e4. \ubb38\uc7a5\ubcc4 \uadfc\uac70\uc640 \ubb38\uc11c \ucd9c\ucc98\ub97c \ubcf4\uace0 \uc9c1\uc811 \ud310\ub2e8\ud558\uc138\uc694."},
glp(){return"\uc544\ub798\uc5d0 \uc804\uccb4 \uc810\uc218\uc640 \ubb38\uc7a5\ubcc4 \uadfc\uac70\ub97c \ucc38\uace0\uc6a9\uc73c\ub85c \ub0a8\uaca8 \ub450\uc5c8\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uacb0\ub860\uc73c\ub85c \ubc1b\uc544\ub4e4\uc774\uc9c0\ub294 \ub9c8\uc138\uc694."},
