grh(){return"\ud3b8\uc9d1 \uae30\ub85d\uc740 \uc815\uc0c1\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4"},
grj(){return"\uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ud3b8\uc9d1 \uae30\ub85d\uc774 \uc5c6\uc2b5\ub2c8\ub2e4"},
gre(){return"\uc774 \uc785\ub825\uc5d0\ub294 \ud3b8\uc9d1 \uae30\ub85d\uc774 \uc5c6\uc2b5\ub2c8\ub2e4(\ubd99\uc5ec\ub123\uc740 \ud14d\uc2a4\ud2b8, PDF, \ub610\ub294 \uae30\ub85d\uc774 \uc9c0\uc6cc\uc9c4 \ud30c\uc77c). \ub530\ub77c\uc11c \ucd9c\ucc98\ub85c\ub294 \ud310\ub2e8\ud560 \uc218 \uc5c6\uace0 \ubcf8\ubb38 \ubd84\uc11d\ub9cc \uac00\ub2a5\ud569\ub2c8\ub2e4."},
rd(a){return"\ud30c\uc77c\uc5d0 \uae30\ub85d\ub41c \ucd1d \ud3b8\uc9d1 \uc2dc\uac04: "+a+"\ubd84"},
rf(a){return"\uc800\uc7a5 \ud69f\uc218: "+a+"\ud68c"},
ra(a){return"\uc0dd\uc131 \ud504\ub85c\uadf8\ub7a8: "+a},
rm(a,b){return"\ubcf8\ubb38\uc758 \ud3b8\uc9d1 \ubc30\uce58 \ud45c\uc2dd\uc774 "+a+"\uac1c\ubfd0\uc778\ub370 \ub0b4\uc6a9\uc740 "+b+"\ub2e8\uc5b4\uc785\ub2c8\ub2e4. \uc0dd\uac01\ud558\uba70 \uc4f0\uba74 \ubcf4\ud1b5 \uc218\uc2ed \uac1c\uac00 \ub0a8\uc73c\ubbc0\ub85c, \uc774 \uc815\ub3c4\ub85c \uc9d1\uc911\ub418\uc5b4 \uc788\ub2e4\uba74 \ub300\uac1c \ud55c \ubc88\uc5d0 \ub4e4\uc5b4\uac04 \uac83(\uc608: \ubd99\uc5ec\ub123\uae30)\uc785\ub2c8\ub2e4."},
rn(a,b,c){return""+a+"\ub2e8\uc5b4\uc5d0 \uae30\ub85d\ub41c \ud3b8\uc9d1 \uc2dc\uac04 "+b+"\ubd84\uc774\uba74 \ubd84\ub2f9 "+c+"\ub2e8\uc5b4\ub85c, \uc2e4\uc81c\ub85c \uae00\uc744 \uc4f0\uba74\uc11c \uc720\uc9c0\ud560 \uc218 \uc788\ub294 \uc18d\ub3c4\ub97c \ud6e8\uc52c \ub118\uc2b5\ub2c8\ub2e4."},
rl(a){return"\ud30c\uc77c\uc5d0 \uae30\ub85d\ub41c \ud3b8\uc9d1 \uc2dc\uac04\uc774 \uac70\uc758 0\uc778\ub370 \ubcf8\ubb38\uc740 "+a+"\ub2e8\uc5b4\uc785\ub2c8\ub2e4."},
rk(a,b){return""+b+"\ub2e8\uc5b4 \ubd84\ub7c9\uc774 "+a+"\ubc88\ub9cc \uc800\uc7a5\ub418\uc5c8\uc2b5\ub2c8\ub2e4."},
grb(){return"\ucc38\uace0: \uc774 \uae30\ub85d\uc740 \uc9c0\uc6b0\uac70\ub098 \ucd08\uae30\ud654\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \uc774\ub984\uc73c\ub85c \uc800\uc7a5, \uc628\ub77c\uc778 \ubcc0\ud658, Google \ubb38\uc11c\uc5d0\uc11c \ub0b4\ubcf4\ub0b4\uae30, \uc0c8 \ud30c\uc77c\ub85c \ubcf5\uc0ac \u2014 \ubaa8\ub450 \uae30\ub85d\uc744 0\uc73c\ub85c \ub9cc\ub4ed\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2e0\ud638\ub294 \ubcf4\uc870 \uc99d\uac70\uc77c \ubfd0 \ub2e8\ub3c5\uc73c\ub85c \uacb0\ub860\uc774 \ub420 \uc218 \uc5c6\uc73c\uba70, \uc2e0\ud638\uac00 \uc5c6\ub2e4\uace0 \uc0ac\ub78c\uc774 \uc37c\ub2e4\ub294 \uc99d\uba85\ub3c4 \ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gu5(){return"\ubd84\uc11d \uc694\uc57d"},
u6(a,b,c,d){return"\uc5d4\uc9c4 "+b+"\uac1c \uc911 "+a+"\uac1c\uac00 \uc644\ub8cc\ub410\uc2b5\ub2c8\ub2e4. \uc804\uccb4 AI \ud655\ub960\uc740 "+c+"%\ub85c \u201c"+d+"\u201d\uc73c\ub85c \ud310\uc815\ub410\uc2b5\ub2c8\ub2e4."},
u_(a,b){return"\uc5d4\uc9c4\ub4e4\uc758 \ud310\ub2e8\uc774 \ub300\uccb4\ub85c \uc77c\uce58\ud569\ub2c8\ub2e4(\ucd5c\uace0 "+a+"%, \ucd5c\uc800 "+b+"%). \uc774 \uacb0\ub860\uc740 \ucda9\ubd84\ud788 \ubbff\uc744 \ub9cc\ud569\ub2c8\ub2e4."},
u0(a,b,c,d){return"\uc5d4\uc9c4\ub4e4\uc758 \ud310\ub2e8\uc774 \uc5c7\uac08\ub9bd\ub2c8\ub2e4. "+a+"\uc740 "+b+"%\uc778\ub370 "+c+"\uc740 "+d+"%\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4. \uc774\ub7f4 \ub550 \uc885\ud569 \uc810\uc218\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uc544\ub798 \ubb38\uc7a5\ubcc4 \uadfc\uac70\ub97c \ud655\uc778\ud558\ub294 \ud3b8\uc774 \ud6e8\uc52c \uc815\ud655\ud569\ub2c8\ub2e4."},
u1(a,b){return"\uc810\uc218\ub97c \ub04c\uc5b4\uc62c\ub9b0 \uac74 \uc8fc\ub85c "+a+"\uc774\uba70, \uc57d "+b+"\ud37c\uc13c\ud2b8\ud3ec\uc778\ud2b8\ub97c \uae30\uc5ec\ud588\uc2b5\ub2c8\ub2e4."},
u3(a){return""+a+"\uac1c \ubb38\uc7a5\uc744 \ubaa8\ub450 \ud6d1\uc5c8\uc9c0\ub9cc \uac15\ud55c AI \uc2e0\ud638\uc120\uc744 \ub118\uc740 \ubb38\uc7a5\uc740 \ud558\ub098\ub3c4 \uc5c6\uc2b5\ub2c8\ub2e4."},
u4(a,b){return""+b+"\uac1c \ubb38\uc7a5 \uc911 "+a+"\uac1c\uac00 \uac15\ud55c AI \uc2e0\ud638\uc120\uc744 \ub118\uc5c8\uc2b5\ub2c8\ub2e4. \ud55c \ubb38\uc7a5\uc529 \uc0b4\ud3b4\ubcfc \uac00\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4."},
gtY(){return"\uc804\uccb4\uc801\uc73c\ub85c \uc0ac\ub78c\uc774 \uc9c1\uc811 \uc4f4 \uae00\ub85c \uc77d\ud799\ub2c8\ub2e4. \ub530\ub85c \ud30c\uace0\ub4e4 \ub9cc\ud55c \ubd80\ubd84\uc740 \uc5c6\uc2b5\ub2c8\ub2e4."},
gtZ(){return"\uc774 \ubb38\uc11c\ub294 \ud68c\uc0c9\uc9c0\ub300\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc810\uc218\ub9cc\uc73c\ub85c \uacb0\ub860 \ub0b4\ub9ac\uae30\uc5d4 \uc704\ud5d8\ud558\ub2c8 \ubb38\uc7a5\ubcc4 \uadfc\uac70\uc640 \ubb38\uc11c \ucd9c\ucc98\ub97c \ud568\uaed8 \ubcf4\uace0 \ud310\ub2e8\ud558\uc138\uc694."},
gtX(){return"\uc2e0\ud638\uac00 AI \uc0dd\uc131\uc774\ub098 \uc7ac\uc791\uc131 \ucabd\uc744 \ub69c\ub837\ud558\uac8c \uac00\ub9ac\ud0b5\ub2c8\ub2e4. \ud45c\uc2dc\ub41c \ubb38\uc7a5\uc744 \ud558\ub098\uc529 \ud655\uc778\ud55c \ub4a4 \uacb0\uc815\ud558\uc138\uc694."},
u2(a){return"\ucc38\uace0\ub85c "+a+"\uac1c \uc5d4\uc9c4\uc774 \uc774\ubc88 \ud22c\ud45c\uc5d0 \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc544 \ud655\uc2e0\ub3c4\ub294 \uc870\uae08 \ub0ae\ucdb0 \ubcf4\uc154\uc57c \ud569\ub2c8\ub2e4. \ubaa8\ub378 \uad00\ub9ac\uc5d0\uc11c \ucc44\uc6b4 \ub4a4 \ub2e4\uc2dc \ub3cc\ub9ac\uba74 \ub354 \uc815\ud655\ud574\uc9d1\ub2c8\ub2e4."},
tT(a){return"AI index < "+a+"%"},
kW(a,b){return"AI index "+a+"%\u2013"+b+"%"},
tS(a){return"AI index \u2265 "+a+"%"},
gtf(){return"\uac15\ud55c AI \uc2e0\ud638 \ubb38\uc7a5 \ube44\uc728"},
