gte(){return"\ud655\uc778\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4\uff08\uc2dc\uac04 \ucd08\uacfc \ub610\ub294 \uc11c\ubc84 \uc751\ub2f5 \uc5c6\uc74c\uff09"},
