gmd(){return'\uc800\uc790, \uc5f0\ub3c4, \uc81c\ubaa9 \uc720\uc0ac\ub3c4\ub97c Crossref \uacf5\uac1c \ub4f1\ub85d \ub370\uc774\ud130\uc640 \ub300\uc870\ud569\ub2c8\ub2e4. \uc808\ub300\uc801\uc778 \ubcf4\uc7a5\uc740 \uc544\ub2c8\uba70, "\ubd88\ud655\uc2e4"\ud560 \uacbd\uc6b0 \uc9c1\uc811 \ud655\uc778\ud558\ub294 \uac83\uc744 \uad8c\uc7a5\ud569\ub2c8\ub2e4.'},
rK(a){return"\uac80\uc99d \ucd9c\ucc98: "+a},
grz(){return"Google Scholar\uc5d0\uc11c \uc218\ub3d9\uc73c\ub85c \ud655\uc778"},
rA(a){return"\ub192\uc740 \uc2e0\ub8b0\ub3c4: \uc874\uc7ac\ud560 \uac00\ub2a5\uc131\uc774 \ub192\uc74c"+a},
rB(a){return"\uff08"+a+"\uc5d0 \ub4f1\ub85d\ub428\uff09"},
mb(a,b){return'\uc800\ub110\uba85 \ubd88\uc77c\uce58: \ubb38\uc11c\uc5d0\ub294 "'+a+'"\ub77c\uace0 \ub418\uc5b4 \uc788\uc9c0\ub9cc, \uac80\uc99d\ub41c \ub4f1\ub85d \uc815\ubcf4\uc5d0\ub294 "'+b+'"\ub77c\uace0 \ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uc778\uc6a9\uc744 \uac80\ud1a0\ud558\uc138\uc694.'},
