glu(){return"\ud328\ub7ec\ud504\ub808\uc774\uc988 \ud754\uc801 \uac10\uc9c0\ub428"},
gnO(){return"\uc774 \ud14d\uc2a4\ud2b8\ub294 \uac10\uc9c0\ub97c \ud68c\ud53c\ud558\uae30 \uc704\ud574 \ud328\ub7ec\ud504\ub808\uc774\uc9d5 \ub3c4\uad6c\uff08QuillBot, Undetectable.ai \ub4f1\uff09\ub85c \ucc98\ub9ac\ub418\uc5c8\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubb38\uc7a5 \ub2e8\uc704\ub85c\ub294 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc77d\ud788\ub354\ub77c\ub3c4 \uc804\uccb4 \ud1b5\uacc4\uc801 \ud2b9\uc9d5\uc740 \uc21c\uc218\ud55c \uc0ac\ub78c\uc758 \uae00\uacfc \ub2e4\ub985\ub2c8\ub2e4. \ud2b9\ud788 \uc8fc\uc758\ud574 \uc8fc\uc138\uc694."},
glv(){return"\uc8fc\uc694 AI \ubb38\uccb4 \ud328\ud134"},
glt(){return"ESL\uff08\ube44\uc6d0\uc5b4\ubbfc\uff09 \ud3b8\ud5a5 \ubcf4\uc815"},
gnE(){return"\uc774 \ud14d\uc2a4\ud2b8\ub294 \ube44\uc6d0\uc5b4\ubbfc \uc791\uc131\uc790\uac00 \uc37c\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ube44\uc6d0\uc5b4\ubbfc\uc5d0\uac8c \ud754\ud55c \ub0ae\uc740 \ud63c\ub780\ub3c4\uc640 \uaddc\uce59\uc801\uc778 \ubb38\ud615\uc740 \uadf8 \uc790\uccb4\ub85c AI\uc758 \ud2b9\uc9d5\uc774 \uc544\ub2c8\ubbc0\ub85c, \uc2dc\uc2a4\ud15c\uc774 \uc624\ud310\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud574 \ud1b5\uacc4 \ubaa8\ub378\uc758 \uac00\uc911\uce58\ub97c \ub0ae\ucdc4\uc2b5\ub2c8\ub2e4."},
