gnN(){return"\ud14d\uc2a4\ud2b8\uc5d0\ub294 \uaddc\uce59\uc801\uc778 \ubd80\ubd84\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \ubcc0\ud654\ud558\ub294 \ubd80\ubd84\uc774 \uacf5\uc874\ud558\uc5ec, \uc0ac\ub78c\uc758 \ucd08\uc548\uc744 AI\uac00 \ub2e4\ub4ec\uc5c8\uac70\ub098 \uc0ac\ub78c\uacfc AI\uc758 \ud611\uc5c5\uc77c \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4."},
gnL(){return"\ubb38\uc7a5 \uae38\uc774\uc640 \ub2e8\uc5b4 \uc120\ud0dd\uc5d0\uc11c \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ubcc0\ud654\uc640 \uac1c\uc778\uc801 \uc2a4\ud0c0\uc77c\uc774 \ub098\ud0c0\ub098\uba70, \ub69c\ub837\ud55c AI\uc758 \uaddc\uce59\uc131\uc740 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
o7(a){return"\uc5b8\uc5b4 \ubaa8\ub378 \ud63c\ub780\ub3c4\uac00 \ub0ae\uc544\uff08"+a+"\uff09\ud14d\uc2a4\ud2b8\uc758 \uc608\uce21 \uac00\ub2a5\uc131\uc774 \ub192\uc73c\uba70, \uc774\ub294 AI \uc0dd\uc131\uc758 \uc9c0\ud45c\uc785\ub2c8\ub2e4"},
o6(a){return"\uc5b8\uc5b4 \ubaa8\ub378 \ud63c\ub780\ub3c4\uac00 \ub192\uc544\uff08"+a+"\uff09\uc0ac\ub78c\uc758 \uae00\uc774 \uc9c0\ub2cc \uc608\uce21 \ubd88\uac00\ub2a5\uc131\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4"},
o8(a){return"\uc5b8\uc5b4 \ubaa8\ub378 \ud63c\ub780\ub3c4\uac00 \uc911\uac04 \uc218\uc900\uc785\ub2c8\ub2e4\uff08"+a+"\uff09"},
