tC(a){return""+a+" \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0439"},
gnC(){return"\u041b\u043e\u043a\u0430\u043b\u044c\u043d\u0430\u044f \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u043f\u043e \u044d\u0442\u0430\u043b\u043e\u043d\u0443"},
gnw(){return"\u042d\u0442\u0430\u043b\u043e\u043d\u043d\u043e\u0433\u043e \u043d\u0430\u0431\u043e\u0440\u0430 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442. \u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0431\u043e\u0442, \u043e \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0442\u043e\u0447\u043d\u043e \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e, \u0447\u0442\u043e \u0438\u0445 \u043f\u0438\u0441\u0430\u043b\u0438 \u0441\u0430\u043c\u0438 \u0443\u0447\u0435\u043d\u0438\u043a\u0438 \u2014 \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u0435 \u0432 \u043a\u043b\u0430\u0441\u0441\u0435, \u2014 \u0438 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0431\u0443\u0434\u0435\u0442 \u0441\u0443\u0434\u0438\u0442\u044c \u043f\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e \u0438\u043c\u0435\u043d\u043d\u043e \u044d\u0442\u043e\u0439 \u0433\u0440\u0443\u043f\u043f\u044b, \u0430 \u043d\u0435 \u043f\u043e \u0435\u0434\u0438\u043d\u043e\u043c\u0443 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043f\u043e\u0440\u043e\u0433\u0443. \u0418\u043c\u0435\u043d\u043d\u043e \u044d\u0442\u043e \u0441\u043d\u0438\u0436\u0430\u0435\u0442 \u043b\u043e\u0436\u043d\u044b\u0435 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u044f \u043d\u0430 \u0442\u0435\u043a\u0441\u0442\u0430\u0445 \u043d\u0435\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u0435\u0439 \u044f\u0437\u044b\u043a\u0430."},
ny(a,b,c){return"\u0412 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435 "+a+" \u043e\u0431\u0440\u0430\u0437\u0446(\u043e\u0432); \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u0435\u0434\u0435\u043b \u043b\u043e\u0436\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0439 \u0432 "+c+"% \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0431\u043b\u044e\u0434\u0430\u043b\u0441\u044f, \u043d\u0443\u0436\u043d\u043e \u043c\u0438\u043d\u0438\u043c\u0443\u043c "+b+". \u0414\u043e \u0442\u0435\u0445 \u043f\u043e\u0440 \u0446\u0438\u0444\u0440\u044b \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043b\u0438\u0448\u044c \u0434\u043b\u044f \u0441\u043f\u0440\u0430\u0432\u043a\u0438 \u0438 \u043d\u0438\u0447\u0435\u0433\u043e \u043f\u043e \u043d\u0438\u043c \u043d\u0435 \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f."},
nx(a){return"\u041f\u0440\u0438 \u043f\u0440\u0435\u0434\u0435\u043b\u0435 \u043b\u043e\u0436\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0439 "+a+"% \u044d\u0442\u043e\u0442 \u0442\u0435\u043a\u0441\u0442 **\u043f\u043e\u043c\u0435\u0447\u0435\u043d**."},
nz(a){return"\u041f\u0440\u0438 \u043f\u0440\u0435\u0434\u0435\u043b\u0435 \u043b\u043e\u0436\u043d\u044b\u0445 \u0441\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u043d\u0438\u0439 "+a+"% \u044d\u0442\u043e\u0442 \u0442\u0435\u043a\u0441\u0442 **\u043d\u0435 \u043f\u043e\u043c\u0435\u0447\u0435\u043d**."},
nA(a,b){return"\u041a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u043e\u0435 p-\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 "+a+" (\u043f\u0440\u043e\u0442\u0438\u0432 "+b+" \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0445 \u043e\u0431\u0440\u0430\u0437\u0446\u043e\u0432)"},
nB(a){return"\u041e\u0446\u0435\u043d\u043a\u0430 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0432 "+a+"-\u043c \u043f\u0440\u043e\u0446\u0435\u043d\u0442\u0438\u043b\u0435 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u043e\u0433\u043e \u043d\u0430\u0431\u043e\u0440\u0430"},
gnv(){return"\u0413\u0430\u0440\u0430\u043d\u0442\u0438\u044f \u043e\u043f\u0438\u0440\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u043e\u0431\u043c\u0435\u043d\u0438\u0432\u0430\u0435\u043c\u043e\u0441\u0442\u044c \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0445 \u043e\u0431\u0440\u0430\u0437\u0446\u043e\u0432 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u0430 \u2014 \u0442\u0430 \u0436\u0435 \u0433\u0440\u0443\u043f\u043f\u0430 \u043b\u044e\u0434\u0435\u0439, \u0442\u043e\u0442 \u0436\u0435 \u0442\u0438\u043f \u0437\u0430\u0434\u0430\u043d\u0438\u044f. \u0415\u0441\u043b\u0438 \u043f\u0438\u0441\u044c\u043c\u043e \u0443\u0447\u0435\u043d\u0438\u043a\u0430 \u0437\u0430\u043c\u0435\u0442\u043d\u043e \u0443\u043b\u0443\u0447\u0448\u0438\u043b\u043e\u0441\u044c \u0438\u043b\u0438 \u0442\u0438\u043f \u0440\u0430\u0431\u043e\u0442\u044b \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0441\u043c\u0435\u043d\u0438\u043b\u0441\u044f, \u043f\u0440\u0435\u0434\u043f\u043e\u0441\u044b\u043b\u043a\u0430 \u0440\u0443\u0448\u0438\u0442\u0441\u044f \u0438 \u043d\u0430\u0431\u043e\u0440 \u043d\u0443\u0436\u043d\u043e \u0441\u043e\u0431\u0440\u0430\u0442\u044c \u0437\u0430\u043d\u043e\u0432\u043e. \u0418 \u0435\u0449\u0451: \u0435\u0441\u043b\u0438 \u0441\u0430\u043c\u0438 \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u044b \u0418\u0418, \u0432\u0441\u044f \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u0441\u043c\u0435\u0449\u0430\u0435\u0442\u0441\u044f \u2014 \u0441\u043e\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u0438\u0445 \u0432 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445."},
